        ? String(unit).trim()
        : null;

msg._latitude =
    latitude !== undefined && latitude !== null
        ? Number(latitude)
        : null;

msg._longitude =
    longitude !== undefined && longitude !== null
        ? Number(longitude)
        : null;

msg._metadata =
    metadata && typeof metadata === 'object' && !Array.isArray(metadata)
        ? metadata
        : {};

msg._event_at =
    timestamp
        ? new Date(timestamp)
        : new Date();

if (Number.isNaN(msg._event_at.getTime())) {
    msg.statusCode = 400;
    msg.payload = { error: 'timestamp inválido' };
    return [null, msg];
}

if (
    msg._latitude !== null &&
    (
        Number.isNaN(msg._latitude) ||
        msg._latitude < -90 ||
        msg._latitude > 90
    )
) {
    msg.statusCode = 400;
    msg.payload = { error: 'latitude inválida' };
    return [null, msg];
}

if (
    msg._longitude !== null &&
    (
        Number.isNaN(msg._longitude) ||
        msg._longitude < -180 ||
        msg._longitude > 180
    )
) {
    msg.statusCode = 400;
    msg.payload = { error: 'longitude inválida' };
    return [null, msg];
}

const allowedSeverity = [
    'info',
    'warning',
    'alert',
    'critical'
];

if (
    msg._severity &&
    !allowedSeverity.includes(msg._severity)
) {
    msg.statusCode = 400;
    msg.payload = {
        error: 'severity inválida',
        allowed: allowedSeverity
    };
    return [null, msg];
}

msg.params = [
    msg._device_code,
    msg._imei
];

return [msg, null];

const rows = msg.payload || [];

if (!rows[0]) {
    msg.statusCode = 404;
    msg.payload = {
        error: 'Dispositivo no encontrado'
    };
    return [null, msg];
}

msg._device = rows[0];

msg.params = [
    msg._device.device_type,
    msg._event_code
];

return [msg, null];

const rows = msg.payload || [];

if (!rows[0]) {
    msg.statusCode = 400;
    msg.payload = {
        error: 'event_code no definido para este tipo de dispositivo',
        event_code: msg._event_code,
        device_type: msg._device.device_type
    };
    return [null, msg];
}

const def = rows[0];

msg._definition = def;

const finalSeverity =
    msg._severity ||
    def.default_severity ||
    'info';

const finalMessage =
    msg._message ||
    def.name ||
    msg._event_code;

const metadata = {
    ...msg._metadata,
    event_code: msg._event_code,
    category: def.category,
    value: msg._value,
    unit: msg._unit,
    latitude: msg._latitude,
    longitude: msg._longitude,
    device_code: msg._device_code,
    imei: msg._imei,
    device_state: msg._device.device_state,
    desired_state: msg._device.desired_state
};

msg._final_severity = finalSeverity;
msg._final_message = finalMessage;
msg._event_metadata = metadata;

msg.params = [
    msg._device.id,
    msg._event_code,
    finalSeverity,
    finalMessage,
    JSON.stringify(metadata),
    msg._event_at
];

return [msg, null];

const rows = msg.payload || [];

if (!rows[0]) {
    msg.statusCode = 500;
    msg.payload = {
        error: 'No fue posible registrar el evento'
    };
    return [null, null, msg];
}

msg._event = rows[0];

const def = msg._definition || {};

if (
    !def.policy_id ||
    def.notify_enabled !== true
) {
    msg._notification = {
        attempted: false,
        status: 'disabled'
    };

    return [null, msg, null];
}

msg.params = [
    msg._device.user_id
];

return [msg, null, null];

const rows = msg.payload || [];
const cfg = rows[0];

if (
    !cfg ||
    cfg.enabled !== true ||
    !cfg.endpoint ||
    !cfg.token_encrypted
) {
    msg._suppressed_reason =
        !cfg
            ? 'gotify_not_configured'
            : (
                cfg.enabled !== true
                    ? 'gotify_disabled'
                    : 'gotify_incomplete'
            );

    msg.params = [
        msg._event.id,
        msg._device.user_id,
        msg._definition.policy_id,
        msg._definition.priority,
        msg._suppressed_reason
    ];

    return [null, msg];
}

msg._gotify = cfg;

msg.params = [
    msg._device.user_id,
    msg._definition.policy_id,
    parseInt(msg._definition.cooldown_s || 0, 10)
];

return [msg, null];

const row = (msg.payload || [])[0] || {};

msg._notification = {
    attempted: false,
    delivery_id: row.id || null,
    status: 'suppressed',
    reason: row.error_message || msg._suppressed_reason
};

return msg;

const row = (msg.payload || [])[0] || {};

if (row.cooldown_active === true) {
    msg.params = [
        msg._event.id,
        msg._device.user_id,
        msg._definition.policy_id,
        msg._definition.priority
    ];

    return [null, msg];
}

return [msg, null];

const row = (msg.payload || [])[0] || {};

msg._notification = {
    attempted: false,
    delivery_id: row.id || null,
    status: 'suppressed',
    reason: 'cooldown_active'
};

return msg;

const def = msg._definition || {};
const device = msg._device || {};
const metadata = msg._event_metadata || {};

function render(template, fallback) {
    let text = template || fallback || '';

    const vars = {
        device_name: device.name || device.unique_id || 'Dispositivo',
        device_code: device.unique_id || msg._device_code || '',
        state: metadata.device_state || device.device_state || '',
        desired_state: metadata.desired_state || device.desired_state || '',
        event_code: msg._event_code || '',
        value:
            metadata.value !== null &&
            metadata.value !== undefined
                ? String(metadata.value)
                : '',
        unit: metadata.unit || ''
    };

    Object.entries(vars).forEach(([key, value]) => {
        text = text.replace(
            new RegExp(`{{${key}}}`, 'g'),
            String(value)
        );
    });

    return text;
}

msg._gotify_title = render(
    def.title_template,
    def.name || msg._event_code
);

msg._gotify_message = render(
    def.message_template,
    msg._final_message
);

msg.params = [
    msg._event.id,
    msg._device.user_id,
    def.policy_id,
    parseInt(def.priority || 5, 10),
    msg._gotify_title,
    msg._gotify_message
];

return msg;

const delivery = (msg.payload || [])[0];

if (!delivery) {
    msg.statusCode = 500;
    msg.payload = {
        error: "No fue posible crear notification_delivery"
    };
    return [null, msg];
}

msg._delivery = delivery;

const token = String(
    msg._gotify.token_encrypted || ""
).trim();

let endpoint = String(
    msg._gotify.endpoint || ""
).trim();

endpoint = endpoint.replace(/\/+$/, "");

if (!endpoint.endsWith("/message")) {
    endpoint += "/message";
}

if (!token) {
    msg.statusCode = 500;
    msg.payload = {
        error: "Token Gotify vacío"
    };
    return [null, msg];
}

msg.method = "POST";
msg.url = endpoint;

msg.headers = {};
msg.headers["content-type"] = "application/json";
msg.headers["x-gotify-key"] = token;

msg.payload = {
    title: msg._gotify_title,
    message: msg._gotify_message,
    priority: parseInt(
        msg._definition.priority || 5,
        10
    )
};

// Diagnóstico seguro: nunca mostrar el token completo.
node.warn({
    gotify_url: msg.url,
    token_length: token.length,
    token_preview:
        token.substring(0, 4) +
        "..." +
        token.substring(token.length - 4),
    headers: {
        "content-type": msg.headers["content-type"],
        "x-gotify-key": "[PRESENTE]"
    }
});

return [msg, null];

const httpStatus = parseInt(msg.statusCode || 0, 10);

const success =
    httpStatus >= 200 &&
    httpStatus < 300;

msg._gotify_http_status = httpStatus;

msg._gotify_response =
    msg.payload !== undefined
        ? msg.payload
        : null;

msg._delivery_status =
    success
        ? 'sent'
        : 'failed';

msg._delivery_error =
    success
        ? null
        : `gotify_http_${httpStatus || 'error'}`;

msg.params = [
    msg._delivery.id,
    msg._delivery_status,
    JSON.stringify({
        http_status: httpStatus,
        body: msg._gotify_response
    }),
    msg._delivery_error
];

return msg;

const rows = msg.payload || [];

if (
    msg._delivery &&
    rows[0]
) {
    msg._notification = {
        attempted: true,
        delivery_id: rows[0].id,
        status: rows[0].status,
        delivered_at: rows[0].delivered_at || null,
        error: rows[0].error_message || null
    };
}

const event = msg._event;

if (!event) {
    msg.statusCode = 500;
    msg.payload = {
        error: 'Evento registrado pero contexto de respuesta no disponible'
    };
    return msg;
}

msg.statusCode = 201;

msg.payload = {
    success: true,
    event_id: event.id,
    device_id: event.device_id,
    event_code: event.event_type,
    severity: event.severity,
    message: event.message,
    metadata: event.metadata,
    created_at: event.created_at,
    notification: msg._notification || {
        attempted: false,
        status: 'disabled'
    }
};

return msg;

msg.statusCode = 500;

msg.payload = {
    error: 'Error interno en eventos/notificaciones',
    detail:
        msg.error && msg.error.message
            ? msg.error.message
            : 'desconocido'
};

return msg;

const {
    device_code,
    imei,
    batt,
    signal,
    state,
    firmware_version,
    timestamp
} = msg.payload || {};

if (!device_code && !imei) {
    msg.statusCode = 400;
    msg.payload = {
        error: 'device_code o imei requerido'
    };
    return [null, msg];
}

const allowedStates = [
    'FACTORY',
    'WAREHOUSE',
    'DISARMED',
    'ARMED',
    'ALERT_MOVING',
    'ALERT_STOPPED',
    'INACTIVE',
    'BATTERY_CRITICAL'
];

msg._device_code =
    device_code
        ? String(device_code).trim().toUpperCase()
        : null;

msg._imei =
    imei
        ? String(imei).trim()
        : null;

msg._batt =
    batt !== undefined && batt !== null
        ? parseInt(batt, 10)
        : null;

msg._signal =
    signal !== undefined && signal !== null
        ? parseInt(signal, 10)
        : null;

msg._state =
    state
        ? String(state).trim().toUpperCase()
        : null;

msg._fw =
    firmware_version
        ? String(firmware_version).trim()
        : null;

if (
    msg._state &&
    !allowedStates.includes(msg._state)
) {
    msg.statusCode = 400;
    msg.payload = {
        error: 'state inválido',
        allowed_states: allowedStates
    };
    return [null, msg];
}

if (
    msg._batt !== null &&
    (
        Number.isNaN(msg._batt) ||
        msg._batt < 0 ||
        msg._batt > 100
    )
) {
    msg.statusCode = 400;
    msg.payload = {
        error: 'batt debe estar entre 0 y 100'
    };
    return [null, msg];
}

if (
    msg._signal !== null &&
    Number.isNaN(msg._signal)
) {
    msg.statusCode = 400;
    msg.payload = {
        error: 'signal inválido'
    };
    return [null, msg];
}

const parsedTs =
    timestamp
        ? new Date(timestamp)
        : new Date();

if (
    Number.isNaN(
        parsedTs.getTime()
    )
) {
    msg.statusCode = 400;
    msg.payload = {
        error: 'timestamp inválido'
    };
    return [null, msg];
}

msg._reported_at =
    parsedTs;

msg.params = [
    msg._device_code,
    msg._imei
];

return [msg, null];

const rows = msg.payload || [];

if (!rows[0]) {
    msg.statusCode = 200;
    msg.payload = {
        ok: true,
        registered: false,
        pending_command: null
    };
    return [null, msg];
}

msg._device = rows[0];

msg.params = [
    msg._batt,
    msg._signal,
    msg._reported_at,
    msg._state,
    msg._fw,
    msg._device.id
];

return [msg, null];

msg._snapshot =
    (msg.payload || [])[0] || {};

msg.params = [
    msg._device.id,
    msg._batt,
    msg._signal,
    msg._reported_at,
    msg._device_code,
    msg._imei,
    msg._fw,
    msg._state
];

return msg;

const rows = msg.payload || [];

msg._telemetry_rows =
    rows[0]
        ? parseInt(rows[0].telemetry_rows || 0, 10)
        : 0;

msg.params = [
    msg._device.id
];

return msg;

const commandRows =
    msg.payload || [];

const command =
    commandRows[0] || null;

msg.statusCode = 200;

msg.payload = {
    ok: true,
    registered: true,
    device_id: msg._device.id,

    device_state:
        msg._snapshot.device_state ||
        msg._device.device_state,

    desired_state:
        msg._snapshot.desired_state ||
        msg._device.desired_state,

    telemetry_rows:
        msg._telemetry_rows || 0,

    pending_command:
        command
            ? {
                cmd_id: command.id,
                command: command.command_type,
                payload: command.command_payload,
                status: command.status,
                delivered_at: command.delivered_at,
                expires_at: command.expires_at
              }
            : null
};

return msg;

msg.statusCode = 500;

msg.payload = {
    error: 'Error interno en reporte',
    detail:
        msg.error && msg.error.message
            ? msg.error.message
            : 'desconocido'
};

return msg;

const pg = global.get('pg');
const bcrypt = global.get('bcrypt');
const jwt = global.get('jwt');
const dbConfig = global.get('dbConfig');
const jwtSecret = global.get('jwtSecret');
const client = new pg.Client(dbConfig);
try {
    const { email, password, full_name, phone } = msg.payload;
    if (!email || !password) {
        msg.statusCode = 400;
        msg.payload = { error: 'Email y password son requeridos' };
        return msg;
    }
    if (password.length < 8) {
        msg.statusCode = 400;
        msg.payload = { error: 'Password debe tener al menos 8 caracteres' };
        return msg;
    }
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(email)) {
        msg.statusCode = 400;
        msg.payload = { error: 'Email invalido' };
        return msg;
    }
    await client.connect();
    const existing = await client.query('SELECT id FROM users WHERE email = $1', [email.toLowerCase()]);
    if (existing.rows.length > 0) {
        msg.statusCode = 409;
        msg.payload = { error: 'El email ya esta registrado' };
        return msg;
    }
    const password_hash = await bcrypt.hash(password, 10);
    const userResult = await client.query('INSERT INTO users (email, password_hash, full_name, phone, role, is_active) VALUES ($1, $2, $3, $4, $5, true) RETURNING id, email, full_name, role', [email.toLowerCase(), password_hash, full_name || null, phone || null, 'customer']);
    const user = userResult.rows[0];
    const tenantResult = await client.query('INSERT INTO tenants (name, owner_user_id, is_active) VALUES ($1, $2, true) RETURNING id', [email.split('@')[0], user.id]);
    msg.statusCode = 201;
    msg.payload = { success: true, user: user, tenant_id: tenantResult.rows[0].id };
    return msg;
} catch (err) {
    node.error('Register: ' + err.message, msg);
    msg.statusCode = 500;
    msg.payload = { error: 'Error interno del servidor' };
